delete from public.lesson_flashcards where lesson_id in ('b1edu-words','b1edu-review'); insert into public.lesson_flashcards(lesson_id,flashcard_id,position) values ('b1edu-words','b1edu-ksztalcenie',0),('b1edu-words','b1edu-wyklad',1),('b1edu-words','b1edu-zajecia',2),('b1edu-words','b1edu-kierunek',3),('b1edu-words','b1edu-stypendium',4),('b1edu-words','b1edu-zaliczyc',5),('b1edu-words','b1edu-ocena',6),('b1edu-words','b1edu-wymaganie',7),('b1edu-review','b1edu-samodzielnie',0),('b1edu-review','b1edu-rozwijac',1),('b1edu-review','b1edu-poglebiac',2),('b1edu-review','b1edu-systematyczny',3),('b1edu-review','b1edu-informacja',4),('b1edu-review','b1edu-wspolpraca',5),('b1edu-review','b1edu-postep',6);
delete from public.questions where lesson_id in ('b1edu-grammar','b1edu-quiz','b1edu-reading-check'); insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b1edu-grammar','Uczę się regularnie, ___ chcę dobrze zdać egzamin.','["ponieważ","chociaż","mimo że"]',0,'Ponieważ вводит реальную причину.',0),('b1edu-grammar','___ kurs jest wymagający, daje mi dużo satysfakcji.','["Chociaż","Ponieważ","Dlatego że"]',0,'Chociaż вводит уступку: трудность не отменяет положительный результат.',1),('b1edu-grammar','Nauczyciel powiedział: «Projekt oddajemy w piątek». W mowie zależnej: Nauczyciel powiedział, ___.','["że projekt oddajemy w piątek","czy projekt oddajemy w piątek","żeby projekt oddaliśmy w piątek"]',0,'Утверждение передаётся через że без кавычек.',2),('b1edu-grammar','Prowadząca zapytała: «Czy rozumiecie zadanie?». Prowadząca zapytała, ___.','["czy rozumiemy zadanie","że rozumiemy zadanie","ponieważ rozumiemy zadanie"]',0,'Общий вопрос в косвенной речи вводится союзом czy.',3),('b1edu-grammar','Составьте: Хотя лекции полезны, я больше всего учусь на практике.','["Chociaż wykłady są przydatne, najwięcej uczę się w praktyce.","Ponieważ wykłady są przydatne, ale uczę się praktyka.","Mimo wykłady, najwięcej uczę praktykę."]',0,'Chociaż соединяет уступку с главным сообщением; uczyć się требует родительного падежа.',4),('b1edu-grammar','Составьте: Преподаватель объяснил, что обратную связь мы получим завтра.','["Prowadzący wyjaśnił, że informację zwrotną otrzymamy jutro.","Prowadzący wyjaśnił, czy informacja zwrotna jutro.","Prowadzący powiedział żeby otrzymujemy informację jutro."]',0,'После wyjaśnił утверждение вводится że; будущее действие выражено otrzymamy.',5),
('b1edu-quiz','Что означает kształcenie?','["образование и обучение","экзамен","расписание"]',0,'Kształcenie — организованный процесс получения знаний и навыков.',0),('b1edu-quiz','Aby ___ przedmiot, muszę oddać wszystkie prace.','["zaliczyć","ocenić się","wykładać do"]',0,'Zaliczyć przedmiot — выполнить требования и получить зачёт.',1),('b1edu-quiz','Które wyrażenie oznacza regularny rozwój?','["robić postępy","stracić zajęcia","oddać kierunek"]',0,'Robić postępy — постепенно улучшать результаты.',2),('b1edu-quiz','___ nie zgadzam się z oceną, rozumiem komentarz nauczyciela.','["Chociaż","Ponieważ","Dlatego"]',0,'Chociaż вводит уступительное придаточное.',3),('b1edu-quiz','Studentka powiedziała, ___ najlepiej uczy się w grupie.','["że","czy","żeby"]',0,'Косвенное утверждение после powiedziała вводится że.',4),('b1edu-quiz','Nauczyciel zapytał, ___ przygotowaliśmy prezentację.','["czy","że","chociaż"]',0,'Косвенный общий вопрос требует czy.',5),('b1edu-quiz','Co pomaga zrozumieć własne błędy?','["konkretna informacja zwrotna","sam kierunek studiów","numer sali"]',0,'Конкретная обратная связь объясняет, что именно исправить.',6),('b1edu-quiz','Выберите естественное сочетание.','["pogłębiać wiedzę","zaliczać postępami","rozwijać wykładem"]',0,'Pogłębiać wiedzę — устойчивое сочетание «углублять знания».',7),('b1edu-quiz','Zajęcia praktyczne są ważne, ___ pozwalają zastosować teorię.','["ponieważ","mimo że","czy"]',0,'Ponieważ называет причину важности практики.',8),('b1edu-quiz','Jak opisać własną strategię nauki?','["Uczę się systematycznie i samodzielnie sprawdzam postępy.","Ocena uczy mnie kierunkiem.","Wykład zalicza informację."]',0,'Первый вариант естественно описывает регулярность и самостоятельную проверку прогресса.',9),
('b1edu-reading-check','Dlaczego Lena zapisała się na kurs?','["Chciała pewniej prowadzić spotkania po polsku","Potrzebowała nowej oceny ze szkoły","Chciała zmienić mieszkanie"]',0,'Ей был нужен польский для профессиональных встреч.',0),('b1edu-reading-check','Co było dla niej trudne na początku?','["Łączenie pracy z regularną nauką","Znalezienie budynku uczelni","Kupienie podręcznika"]',0,'Главной трудностью было совмещать работу и систематические занятия.',1),('b1edu-reading-check','Jaką metodę zaproponował prowadzący?','["Krótkie zadania związane z jej pracą","Naukę wyłącznie list słów","Rezygnację z pracy w grupie"]',0,'Преподаватель предложил небольшие практические задания из её рабочего контекста.',2),('b1edu-reading-check','Co powiedziała Lena po prezentacji?','["Że pierwszy raz mówiła bez przygotowanego tekstu","Że nie przyszła na zajęcia","Że zmieniła kierunek studiów"]',0,'Она отметила, что впервые выступала без заранее написанного текста.',3),('b1edu-reading-check','Dlaczego informacja zwrotna była użyteczna?','["Wskazywała mocne strony i konkretny kolejny krok","Zawierała tylko końcową ocenę","Nie dotyczyła prezentacji"]',0,'Обратная связь показывала и успех, и понятный следующий шаг.',4),('b1edu-reading-check','Jaki wniosek wyciągnęła Lena?','["Postęp zależy od systematycznej praktyki, nie tylko od talentu","Najlepiej uczyć się bez celu","Każdy kurs powinien być łatwy"]',0,'Лена связала прогресс с регулярной осмысленной практикой.',5);
