olskiFlow","verified_at":"2026-08-29"}'),('b1edu-systematyczny','systematyczny','систематический','Systematyczna nauka daje trwałe efekty.',418,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1edu-informacja','informacja zwrotna','обратная связь','Nauczyciel przekazał konkretną informację zwrotną.',419,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1edu-wspolpraca','współpraca','сотрудничество','Współpraca w grupie uczy odpowiedzialności.',420,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1edu-postep','robić postępy','делать успехи','Dzięki regularnym ćwiczeniom robię postępy.',421,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}') on conflict(id) do update set polish=excluded.polish,translation=excluded.translation,example=excluded.example,position=excluded.position,is_active=excluded.is_active,source_metadata=excluded.source_metadata;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b1edu-kurs-ktory-zmienil-sposob-nauki','b1-education','Kurs, który zmienił sposób nauki','Как цель, практика и обратная связь помогают учиться','B1',8,'🎓','["Lena pracuje w firmie informatycznej i coraz częściej prowadzi spotkania z polskimi klientami. Chociaż dobrze rozumiała rozmówców, brakowało jej pewności podczas dłuższych wypowiedzi. Dlatego zapisała się na wieczorowy kurs języka biznesowego, żeby rozwijać umiejętności potrzebne w pracy.","Początkowo trudno jej było łączyć obowiązki zawodowe z systematyczną nauką. Prowadzący powiedział, że nie musi codziennie spędzać dwóch godzin nad podręcznikiem. Zaproponował natomiast krótkie zadania: podsumowanie spotkania, wiadomość do klienta albo dwuminutową prezentację.","Po miesiącu uczestnicy przygotowali prezentacje w małych grupach. Lena wyjaśniła, że pierwszy raz mówiła bez wcześniej napisanego tekstu. Koleżanki zadawały pytania, a prowadzący przekazał jej informację zwrotną. Najpierw wskazał mocne strony, a następnie zaproponował jedno konkretne ćwiczenie nad wymową.","Lena nadal popełnia błędy, mimo że robi wyraźne postępy. Zrozumiała, że skuteczne kształcenie nie polega wyłącznie na zdobywaniu ocen. Najważniejsze są jasny cel, samodzielna praca i współpraca z ludźmi, którzy potrafią powiedzieć, co już działa i co warto poprawić."]','{"rozmówców":{"lemma":"rozmówca","translation":"собеседник","part_of_speech":"существительное"},"brakowało":{"lemma":"brakować","translation":"не хватать","part_of_speech":"глагол"},"pewności":{"lemma":"pewność","translation":"уверенность","part_of_speech":"существительное"},"wypowiedzi":{"lemma":"wypowiedź","translation":"высказывание","part_of_speech":"существительное"},"wieczorowy":{"lemma":"wieczorowy","translation":"вечерний","part_of_speech":"прилагательное"},"łączyć":{"lemma":"łączyć","translation":"совмещать","part_of_speech":"глагол"},"obowiązki":{"lemma":"obowiązek","translation":"обязанность","part_of_speech":"существительное"},"prowadzący":{"lemma":"prowadzący","translation":"преподаватель; ведущий","part_of_speech":"существительное"},"podsumowanie":{"lemma":"podsumowanie","translation":"резюме; подведение итогов","part_of_speech":"существительное"},"uczestnicy":{"lemma":"uczestnik","translation":"участник","part_of_speech":"существительное"},"wskazał":{"lemma":"wskazać","translation":"указать","part_of_speech":"глагол"},"wymową":{"lemma":"wymowa","translation":"произношение","part_of_speech":"существительное"},"popełnia":{"lemma":"popełniać","translation":"совершать","part_of_speech":"глагол"},"wyraźne":{"lemma":"wyraźny","translation":"заметный; явный","part_of_speech":"прилагательное"},"wyłącznie":{"lemma":"wyłącznie","translation":"исключительно","part_of_speech":"наречие"},"zdobywaniu":{"lemma":"zdobywać","translation":"получать; приобретать","part_of_speech":"глагол"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29","comprehension_lesson_id":"b1edu-reading-check"}',27,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
